  "Invoice numbers must be unique within a financial year (India, GST Rule 46). Including {FY} keeps bill references unique across years.": "يجب أن تكون أرقام الفواتير فريدة داخل السنة المالية (الهند، قاعدة GST رقم 46). إضافة {FY} تُبقي مراجع الفواتير فريدة عبر السنوات.",  // ar: check
  "Invoice numbers usually must be unique within a financial year. Including {FY} keeps bill references unique across years.": "يجب عادةً أن تكون أرقام الفواتير فريدة داخل السنة المالية. إضافة {FY} تُبقي مراجع الفواتير فريدة عبر السنوات.",
  "Next number: ": "الرقم التالي: ",
  "Numbers start again at 1 each year without the year in them, so two bills can share a number. Add {FY} to keep them apart.": "تبدأ الأرقام من 1 كل سنة دون أن تتضمن السنة، فقد تتشارك فاتورتان الرقم نفسه. أضف {FY} للتمييز بينهما.",
  "Numbers start again at 1 each month without the month in them, so bills in one year can share a number. Add {MM} (and {FY}).": "تبدأ الأرقام من 1 كل شهر دون أن تتضمن الشهر، فقد تتشارك فواتير السنة الواحدة رقمًا. أضف {MM} (و{FY}).",
  "The running number shown is from the current setting; it is worked out again when you save.": "الرقم الجاري المعروض وفق الإعداد الحالي، ويُحتسب من جديد عند الحفظ.",
  "Vouchers saved": "السندات المحفوظة",
  "Next number now": "الرقم التالي الآن",
