  "month": "الشهر",
  "Pad to 0 to 9 digits.": "عدد الخانات من 0 إلى 9.",
  "{kind} numbering saved. Next number: {number}.": "تم حفظ ترقيم {kind}. الرقم التالي: {number}.",
