  "Tax ID": "الرقم الضريبي",
  "leave blank if unregistered": "اتركه فارغًا إن لم تكن مسجلة",
  "Building, street\nCity, PIN": "المبنى، الشارع\nالمدينة، الرمز البريدي",
  "printed on invoices; Enter on a blank line moves on": "يُطبع على الفواتير؛ Enter على سطر فارغ ينقلك إلى الحقل التالي",
  "Invoices": "الفواتير",
  "HSN/SAC digits on invoices": "عدد خانات HSN/SAC على الفواتير",  // ar: check
  "By last year's turnover; e-invoices and e-way bills check codes against it.": "حسب مبيعات السنة الماضية؛ تتحقق الفواتير الإلكترونية وبوالص e-way من الرموز وفقه.",  // ar: check
  "4 (turnover up to ₹5 crore)": "4 (مبيعات حتى 5 كرور روبية)",  // ar: check
