  "Tax invoices show the supplier's name, address and tax ID.": "تُظهر الفواتير الضريبية اسم المورد وعنوانه ورقمه الضريبي.",
  "Tax invoices show the supplier's name, address and tax ID. The state decides whether a sale is within the state or to another state.": "تُظهر الفواتير الضريبية اسم المورد وعنوانه ورقمه الضريبي. وتحدد المنطقة ما إذا كان البيع داخلها أو إلى منطقة أخرى.",
