  "Applicable from": "يسري من",
  "percent; 0 for exempt or nil-rated": "نسبة مئوية؛ 0 للمعفى أو الخاضع للصفر",
  "This is saved as a new rate change. The {percent}% rate for {code} from {date} stays; delete it from the list (Alt+D) if it no longer applies.": "يُحفظ هذا كتغيير جديد للنسبة. تبقى نسبة {percent}% للرمز {code} من {date}؛ احذفها من القائمة (Alt+D) إن لم تعد سارية.",
  "Type an HSN/SAC code or a tax category.": "اكتب رمز HSN/SAC أو فئة ضريبية.",
  "Enter the rate as a percent from 0 to 100, such as 18.": "أدخل النسبة مئويةً من 0 إلى 100، مثل 18.",
  "{code}: {percent}% from {date} saved.": "تم حفظ {code}: ‏{percent}% من {date}.",
  "Delete the {percent}% rate for {code} from {date}?": "حذف نسبة {percent}% للرمز {code} من {date}؟",
