  "Add a rate…": "إضافة نسبة…",
  "No rates yet. Press Enter or Alt+C to add the first one.": "لا توجد نسب بعد. اضغط Enter أو Alt+C لإضافة أول نسبة.",
  "Rate %": "النسبة %",
  "An item takes the rate of the longest code in this list that its own code starts with: 8471 covers 84713010 unless 847130 has a rate of its own. A rate applies from its date until the next change for the same code.": "يأخذ الصنف نسبة أطول رمز في هذه القائمة يبدأ به رمزه: 8471 يشمل 84713010 ما لم يكن لـ 847130 نسبة خاصة. تسري النسبة من تاريخها حتى التغيير التالي للرمز نفسه.",
  "Move to a rate to delete it.": "انتقل إلى نسبة لحذفها.",
  "Add Rate": "إضافة نسبة",
  "Save": "حفظ",
