  "Blank street, city and postal code are taken from the company address (Company details), as shown in grey. These details sync with the company's books.": "الشارع والمدينة والرمز البريدي الفارغة تؤخذ من عنوان الشركة (بيانات الشركة)، كما يظهر باللون الرمادي. تُزامَن هذه البيانات مع دفاتر الشركة.",
  "{value} (from the company address)": "{value} (من عنوان الشركة)",
