  "Payable tax for the period": "الضريبة المستحقة الدفع للفترة",
  "Worked out from the books for checking before you file on EmaraTax. Every standard-rated sale is shown in the company's own emirate; all VAT on expenses is treated as recoverable; reverse charge, imports and tourist refunds are not worked out yet. Enter opens the Day Book.": "محسوبة من الدفاتر للمراجعة قبل التقديم على منصة EmaraTax. تظهر كل مبيعات النسبة الأساسية في إمارة الشركة؛ وتُعامل كل ضريبة المصروفات على أنها قابلة للاسترداد؛ ولم تُحتسب بعد آلية الاحتساب العكسي والواردات ومستردات السياح. يفتح Enter دفتر اليومية.",
