  "Net VAT credit": "صافي الرصيد الدائن",
  "Worked out from the books for checking before you file with ZATCA. All VAT on purchases is treated as recoverable; purchases without the supplier's VAT number are left out. Imports, the reverse charge, corrections and carried-forward credit are not worked out. Enter opens the Day Book.": "محسوبة من الدفاتر للمراجعة قبل التقديم إلى زاتكا. تُعامل كل ضريبة المشتريات على أنها قابلة للاسترداد، وتُستبعد المشتريات التي ليس لمورّدها رقم ضريبي. لا تُحتسب الواردات والاحتساب العكسي والتصحيحات والرصيد المرحّل. يفتح Enter دفتر اليومية.",
  "VAT Return": "إقرار ضريبة القيمة المضافة",
