  "Values excluding VAT (whole pounds)": "القيم بدون الضريبة (جنيه كامل)",
  "VAT due on sales and other outputs": "الضريبة المستحقة على المبيعات والمخرجات الأخرى",
  "VAT due on acquisitions of goods from the EU": "الضريبة المستحقة على السلع المقتناة من الاتحاد الأوروبي",
  "Northern Ireland only; not worked out": "لأيرلندا الشمالية فقط؛ غير محتسب",
