  "Total value of purchases and all other inputs excluding VAT": "إجمالي قيمة المشتريات وجميع المدخلات الأخرى بدون الضريبة",
  "Total value of supplies of goods to EU member states": "إجمالي قيمة توريدات السلع إلى دول الاتحاد الأوروبي",
  "Total value of acquisitions of goods from EU member states": "إجمالي قيمة السلع المقتناة من دول الاتحاد الأوروبي",
