  "into Northern Ireland": "إلى أيرلندا الشمالية",
  "Northern Ireland only": "لأيرلندا الشمالية فقط",
  "Worked out from the books for checking before you submit to HMRC. All VAT on purchases is treated as reclaimable; the reverse charge, postponed import VAT, acquisition VAT (Box 2) and the Flat Rate, Cash and Annual Accounting schemes are not worked out. {key} saves the Making Tax Digital JSON body for the period (with \"finalised\" false); KhataOS does not submit it. Enter opens the Day Book.": "محسوبة من الدفاتر للمراجعة قبل التقديم إلى HMRC. تُعامل كل ضريبة المشتريات على أنها قابلة للاسترداد؛ ولا تُحتسب آلية الاحتساب العكسي وضريبة الاستيراد المؤجلة وضريبة الاقتناء (الخانة 2) وأنظمة النسبة الثابتة والمحاسبة النقدية والسنوية. يحفظ {key} محتوى JSON لنظام Making Tax Digital للفترة (مع ⁦\"finalised\": false⁩)؛ ولا يرسله KhataOS. يفتح Enter دفتر اليومية.",
