  "Net outward supplies": "صافي التوريدات الصادرة",
  "Credit and debit notes are shown at their own values; B2C small and the HSN summary are net of credit notes. {json} saves a draft GSTR-1 JSON in the offline-tool layout. It is not validated against the GST portal schema: open it in the GST Returns Offline Tool and check it before uploading. {bulk} saves the period's B2B, SEZ and export invoices and credit notes as one e-invoice JSON file for the IRP's bulk tool.": "تظهر إشعارات الدائن والمدين بقيمها الخاصة؛ أما توريدات ⁦B2C⁩ الصغيرة وملخص ⁦HSN⁩ فبعد خصم إشعارات الدائن. يحفظ {json} مسودة ⁦GSTR-1 JSON⁩ بتنسيق الأداة غير المتصلة، دون التحقق منها وفق مخطط بوابة ⁦GST⁩: افتحها في أداة ⁦GST Returns Offline Tool⁩ وراجعها قبل الرفع. ويحفظ {bulk} فواتير الفترة وإشعارات الدائن من نوع ⁦B2B⁩ و⁦SEZ⁩ والتصدير في ملف ⁦JSON⁩ واحد للفوترة الإلكترونية لأداة الرفع المجمّع في ⁦IRP⁩.",  // ar: check
  "Draft GSTR-1 saved to {file}. Check it in the GST offline tool before filing.": "حُفظت مسودة ⁦GSTR-1⁩ في {file}. راجعها في أداة ⁦GST⁩ غير المتصلة قبل التقديم.",
