  "(A)(5) All other ITC": "⁦(A)(5)⁩ جميع أرصدة ضريبة المدخلات الأخرى",  // ar: check
  "Net is output tax less ITC for each tax on its own. The order of using IGST, CGST and SGST credit against each other (CGST Act s.49, Rule 88A) is not applied. Reverse-charge tax (3.1(d)) is paid in cash; reversals and the full Table 4 are in the report Input tax credit (GSTR-3B Table 4). A negative net is credit left over. Enter on 3.1 opens GSTR-1.": "الصافي هو ضريبة المخرجات ناقص رصيد المدخلات لكل ضريبة على حدة. لا يُطبَّق ترتيب استخدام أرصدة ⁦IGST⁩ و⁦CGST⁩ و⁦SGST⁩ مقابل بعضها (⁦CGST Act s.49, Rule 88A⁩). تُدفع ضريبة الاحتساب العكسي (⁦3.1(d)⁩) نقدًا؛ وتجد عكس الرصيد والجدول 4 كاملًا في تقرير رصيد ضريبة المدخلات (⁦GSTR-3B Table 4⁩). الصافي السالب رصيد متبقٍّ. يفتح Enter على البند 3.1 نموذج ⁦GSTR-1⁩.",  // ar: check
