  "It works until it expires or you revoke it. Treat it like a key: anyone with it can open the books. It is shown only once.": "يعمل الرمز حتى تنتهي صلاحيته أو تلغيه. عامله كالمفتاح: كل من يملكه يستطيع فتح الدفاتر. يُعرض مرة واحدة فقط.",
  "Copy": "نسخ",
