  "Office network: this computer must be on the same network as the server PC, and KhataOS must be open there.": "شبكة المكتب: يجب أن يكون هذا الحاسوب على شبكة حاسوب الخادم نفسها، وأن يكون KhataOS مفتوحًا هناك.",
  "Company: {name}": "الشركة: {name}",
