  "Browser Access · read-only reports without installing KhataOS": "الوصول من المتصفح · تقارير للقراءة فقط دون تثبيت KhataOS",
  "This company syncs through the encrypted relay, which can't read the books, so there is no browser access. Send a Viewer invite or an accountant file instead.": "تُزامَن هذه الشركة عبر الخادم الوسيط المشفّر الذي لا يستطيع قراءة الدفاتر، لذا لا يتوفر وصول من المتصفح. أرسل دعوة مشاهد أو ملف محاسب بدلًا من ذلك.",
  "Create a {viewer} invite in Remote Access. The invite screen shows the company id and token to enter on this page. Viewers see reports only.": "أنشئ دعوة {viewer} من الوصول عن بُعد. تعرض شاشة الدعوة معرّف الشركة ورمز الوصول لإدخالهما في هذه الصفحة. لا يرى المشاهدون إلا التقارير.",
