  "Notes": "ملاحظات",
  "The private key and the CSID secrets are kept only in the file above, readable by your user account alone: never in the company file, its backups, the audit trail or sync. A copied or restored company must be onboarded again. {restart}: start again with a new device.": "يُحفظ المفتاح الخاص وأسرار ⁦CSID⁩ في الملف أعلاه فقط، ولا يقرؤه إلا حساب المستخدم الخاص بك، ولا تُحفظ أبدًا في ملف الشركة أو نسخه الاحتياطية أو سجل التدقيق أو المزامنة. يجب ربط الشركة المنسوخة أو المستعادة من جديد. {restart}: البدء من جديد بجهاز جديد.",
  "Type sandbox (developer portal), simulation or production.": "اكتب ⁦sandbox⁩ (بوابة المطورين) أو ⁦simulation⁩ أو ⁦production⁩.",
  "The OTP is the number shown on the Fatoora portal.": "رمز التحقق (⁦OTP⁩) هو الرقم الظاهر في بوابة فاتورة.",
  "Invoice types are four digits of 0 and 1, such as 1100.": "أنواع الفواتير أربعة أرقام من 0 و1، مثل ⁦1100⁩.",
  "Onboard this computer with ZATCA production? Its invoices will then be legally issued through ZATCA.": "ربط هذا الجهاز ببيئة الإنتاج لدى ⁦ZATCA⁩؟ ستصدر فواتيره بعدها رسميًا عبر ⁦ZATCA⁩.",
  "Start again with a new device id and key? This computer must then be onboarded with a new OTP.": "البدء من جديد بمعرّف جهاز ومفتاح جديدين؟ يجب بعدها ربط هذا الجهاز برمز تحقق (⁦OTP⁩) جديد.",
