  "ZATCA Submission": "الإرسال إلى هيئة الزكاة والضريبة والجمارك (⁦ZATCA⁩)",
  "This computer is not onboarded with ZATCA yet: open ZATCA Onboarding first.": "هذا الجهاز غير مربوط مع ⁦ZATCA⁩ بعد: افتح «ربط ⁦ZATCA⁩» أولًا.",
  "Not sent to ZATCA yet. {key} stamps the e-invoice and sends it: a standard invoice for clearance, a simplified one for reporting.": "لم تُرسل إلى ⁦ZATCA⁩ بعد. يختم {key} الفاتورة الإلكترونية ويرسلها: الفاتورة القياسية للاعتماد، والمبسطة للإبلاغ.",
