  "ZATCA returned the cleared invoice with its own stamp and QR code: give the buyer this XML ({key} saves it). The print uses ZATCA's QR code.": "أعادت ⁦ZATCA⁩ الفاتورة المعتمدة بختمها ورمز QR الخاص بها: سلّم المشتري ملف XML هذا (يحفظه {key}). تستخدم الطباعة رمز QR الصادر من ⁦ZATCA⁩.",
  "Correct the problem and send again ({key}). A refused invoice keeps its counter; ZATCA accepts gaps.": "صحّح المشكلة وأعد الإرسال ({key}). تحتفظ الفاتورة المرفوضة بعدّادها، وتقبل ⁦ZATCA⁩ الفجوات في التسلسل.",
