  // ------------------------------- ZATCA status texts and IVA rows shown through t()
  "Onboard this computer: pick the environment, get an OTP from the Fatoora portal and enter it here.": "اربط هذا الجهاز: اختر البيئة، واحصل على رمز تحقق (⁦OTP⁩) من بوابة فاتورة وأدخله هنا.",
  "Ready: e-invoices are stamped, and Submit sends them to ZATCA (clearance for standard, reporting for simplified).": "جاهز: تُختم الفواتير الإلكترونية، ويرسلها «الإرسال» إلى ⁦ZATCA⁩ (الاعتماد للقياسية، والإبلاغ للمبسطة).",
  "Enter an OTP from the Fatoora portal to get the compliance CSID.": "أدخل رمز تحقق (⁦OTP⁩) من بوابة فاتورة للحصول على شهادة الامتثال (⁦CSID⁩).",
  "Run onboarding again (no OTP needed) to finish the compliance checks and get the production CSID.": "أعد الربط (دون رمز تحقق) لإكمال فحوص الامتثال والحصول على شهادة الإنتاج (⁦CSID⁩).",
  "standard invoice": "فاتورة ضريبية قياسية",
  "standard credit note": "إشعار دائن قياسي",
  "standard debit note": "إشعار مدين قياسي",
  "simplified invoice": "فاتورة ضريبية مبسطة",
  "simplified credit note": "إشعار دائن مبسط",
  "simplified debit note": "إشعار مدين مبسط",
  "exempt": "معفى",
  // ------------------------------- TDS/TCS reports, statements and salary estimate (India: tds.ts)
  " (overdue)": " (متأخر)",
  "Paid / Credited": "المدفوع / المقيَّد",
  "TDS Deducted": "الضريبة المستقطعة",
  "No TDS in this period. Press F2 to change it.": "لا استقطاع في هذه الفترة. اضغط F2 لتغييرها.",
  "Mark a ledger under Duties & Taxes as TDS payable.": "حدّد حسابًا تحت الضرائب والرسوم كحساب ضريبة استقطاع مستحقة.",
  "Nothing deducted in this period.": "لم يُستقطع شيء في هذه الفترة.",
  "No TDS paid in this period.": "لم تُسدَّد ضريبة استقطاع في هذه الفترة.",
  "Paid / credited is the amount booked to ledgers with a nature of payment for a party; TDS deducted is what was credited to TDS payable ledgers in those vouchers; deposited is the payments out of those ledgers. Outstanding is the closing balance of the ledgers marked for that nature. Pay-by dates are the old Rule 30's (7th of the next month; 30 April for March), reported unchanged under the Income-tax Rules 2026 by secondary sources. Enter on a nature lists its deductions.": "«المدفوع / المقيَّد» هو المبلغ المسجل على حسابات لها طبيعة دفعة لطرف ما؛ و«الضريبة المستقطعة» ما قُيّد دائنًا لحسابات ضريبة الاستقطاع المستحقة في تلك السندات؛ و«المودَع» هو المدفوعات من تلك الحسابات. و«المتبقي» هو الرصيد الختامي للحسابات المحددة لتلك الطبيعة. مواعيد السداد هي مواعيد القاعدة 30 القديمة (اليوم 7 من الشهر التالي؛ و30 أبريل لشهر مارس)، وتذكر مصادر ثانوية أنها لم تتغير في قواعد ضريبة الدخل لعام 2026. يعرض Enter على طبيعة ما استقطاعاتها.",  // ar: check
  "Received / Debited": "المستلم / المقيَّد مدينًا",
  "TCS Collected": "الضريبة المحصّلة",
  "No TCS in this period. Press F2 to change it.": "لا تحصيل في هذه الفترة. اضغط F2 لتغييرها.",
  "Mark a ledger under Duties & Taxes as TCS payable.": "حدّد حسابًا تحت الضرائب والرسوم كحساب ضريبة تحصيل مستحقة.",
  "Nothing collected in this period.": "لم يُحصَّل شيء في هذه الفترة.",
  "No TCS paid in this period.": "لم تُسدَّد ضريبة تحصيل في هذه الفترة.",
  "Received / debited is what buyers pay through ledgers with a nature of collection, GST included (the Act taxes the amount payable by the buyer; whether GST counts is not settled). TCS collected is what was credited to TCS payable ledgers; deposited is the payments out of those ledgers. TCS is due within seven days from the end of the month (old Rule 37CA; the 2026 rules' date is from secondary sources). Enter on a nature lists its rows.": "«المستلم / المقيَّد مدينًا» هو ما يدفعه المشترون عبر حسابات لها طبيعة تحصيل، شاملًا ⁦GST⁩ (يُخضع القانون المبلغ المستحق على المشتري؛ ولم يُحسم احتساب ⁦GST⁩). «الضريبة المحصّلة» ما قُيّد دائنًا لحسابات ضريبة التحصيل المستحقة؛ و«المودَع» هو المدفوعات من تلك الحسابات. تستحق ضريبة التحصيل خلال سبعة أيام من نهاية الشهر (القاعدة 37CA القديمة؛ وموعد قواعد 2026 من مصادر ثانوية). يعرض Enter على طبيعة ما سطورها.",  // ar: check
