  "The quarter is 1 (Apr-Jun) to 4 (Jan-Mar).": "الربع من 1 (أبريل-يونيو) إلى 4 (يناير-مارس).",
  "No challan paid in this quarter.": "لم يُسدَّد أي إيصال في هذا الربع.",
