  "Deductor details: {key} on the quarterly report. Challan bank details: Enter on a challan there. PANs and party details: the ledger.": "بيانات المستقطِع: {key} في التقرير الربع سنوي. بيانات البنك لإيصال السداد: Enter على الإيصال هناك. أرقام ⁦PAN⁩ وبيانات الأطراف: من الحساب.",
