  "{csv} saves this data as CSV; {file} saves the statement text file (2026-27 onward). Notes:": "يحفظ {csv} هذه البيانات بصيغة CSV؛ ويحفظ {file} ملف البيان النصي (من 2026-27 فصاعدًا). ملاحظات:",
  "Statement CSV": "البيان CSV",
  "Statement data saved to {file}. For filing, save the statement file ({key}) and validate it with the FVU.": "حُفظت بيانات البيان في {file}. للتقديم، احفظ ملف البيان ({key}) وتحقّق منه بأداة ⁦FVU⁩.",
  "Certificate": "شهادة",
  "Declaration": "إقرار",
  "No collections in this quarter. Press F2 to pick another.": "لا تحصيلات في هذا الربع. اضغط F2 لاختيار ربع آخر.",
  "Collectee": "المحصَّل منه",
  "Code · nature": "الرمز · الطبيعة",
  "Flag": "العلامة",
  "{file} saves the Form 143 text file once the deductor's details ({deductor}) and the challans' bank details are in. Rates are the Income-tax Act 2025 s.394 Table as amended by the Finance Act 2026 (2% for liquor, tendu leaves, timber, forest produce, scrap and minerals; 1% for a motor vehicle over ₹10 lakh). Validate the file with the official FVU.": "يحفظ {file} الملف النصي للنموذج ⁦143⁩ بعد إدخال بيانات المستقطِع ({deductor}) وبيانات البنك لإيصالات السداد. النسب هي جدول المادة ⁦s.394⁩ من قانون ضريبة الدخل 2025 بتعديل قانون المالية 2026 (2% للمشروبات الكحولية وأوراق التندو والأخشاب ومنتجات الغابات والخردة والمعادن؛ و1% للمركبة التي تزيد قيمتها على ⁦₹10 lakh⁩). تحقّق من الملف بأداة ⁦FVU⁩ الرسمية.",  // ar: check
  "TDS Non-resident Statement": "بيان ضريبة الاستقطاع لغير المقيمين",
  "No country": "لا توجد دولة",
  "Treaty": "الاتفاقية",
  "Act": "القانون",
  "No payments to non-residents in this quarter.": "لا مدفوعات لغير المقيمين في هذا الربع.",
  "Rates are yours": "النسب من إدخالك",
  "Remittance": "التحويل",
  "Basis": "الأساس",
  "Enter the rate, country and nature of remittance in the party ledger's Non-resident terms (alter the ledger; they show for a party abroad). Below 20% the file needs the payee's foreign address, email, phone and tax number.": "أدخل النسبة والدولة وطبيعة التحويل في «شروط غير المقيم» بحساب الطرف (عدّل الحساب؛ تظهر للطرف في الخارج). دون 20% يحتاج الملف إلى عنوان المستفيد في الخارج وبريده الإلكتروني وهاتفه ورقمه الضريبي.",
  "Deductor (TDS / TCS statements)": "المستقطِع (بيانات الاستقطاع والتحصيل)",
  "TAN": "رقم ⁦TAN⁩",
