  "Keep the password safe: without it nobody can restore this backup, and KhataOS doesn't keep it.": "احفظ كلمة المرور في مكان آمن: بدونها لا يستطيع أحد استعادة هذه النسخة، ولا يحتفظ بها KhataOS.",
