  "Checking the backup…": "جارٍ فحص النسخة الاحتياطية…",
  "Automatic backups of {company}": "النسخ الاحتياطية التلقائية لـ {company}",
  "Automatic backups are checked like the ones you make. To keep the newest {n}, older automatic backups are deleted; your own backups and other files in the folder are never touched.": "تُفحص النسخ التلقائية كما تُفحص النسخ التي تصنعها. للاحتفاظ بأحدث {n} نسخ تُحذف النسخ التلقائية الأقدم، ولا تُمس أبدًا نسخك الخاصة ولا الملفات الأخرى في المجلد.",
  "Before a Tally import into a company with books, a restore that replaces, a sync rebase or a move to another relay, KhataOS always backs up first, even with automatic backups off.": "قبل الاستيراد من Tally إلى شركة فيها دفاتر، أو استعادة تستبدل الشركة، أو إعادة بناء المزامنة، أو النقل إلى خادم وسيط آخر، ينسخ KhataOS احتياطيًا أولًا دائمًا، حتى إن كانت النسخ التلقائية متوقفة.",
  "On a phone these backups stay inside the app, and uninstalling KhataOS deletes them. Use Data → Backup to save a copy somewhere else.": "على الهاتف تبقى هذه النسخ داخل التطبيق، وإلغاء تثبيت KhataOS يحذفها. استخدم البيانات ← نسخ احتياطي لحفظ نسخة في مكان آخر.",
  "Only an Accountant or the Owner can change these settings.": "لا يغيّر هذه الإعدادات إلا المحاسب أو المالك.",
  "Automatic backups": "النسخ الاحتياطية التلقائية",
