  "A new company file is the safest: nothing is overwritten, and you can compare the two. Replacing keeps the current file as a copy beside it, and backs it up first.": "ملف شركة جديد هو الأكثر أمانًا: لا يُكتب فوق أي شيء، ويمكنك المقارنة بين الاثنين. الاستبدال يحتفظ بالملف الحالي نسخةً بجانبه، وينسخه احتياطيًا أولًا.",
