  "{company} already has books. KhataOS backs it up first, then imports into it. For a first migration, a new company is safer. Import into {company}?": "لدى {company} دفاتر بالفعل. ينسخها KhataOS احتياطيًا أولًا ثم يستورد إليها. للترحيل الأول، الشركة الجديدة أكثر أمانًا. هل تستورد إلى {company}؟",
